import os
import sqlite3
import sys
import unittest

sys.path.insert(0, os.getcwd())

from src.repository import initialize
from src.service import get_document, list_documents


class DocumentSecurityTests(unittest.TestCase):
    def setUp(self):
        self.connection = sqlite3.connect(":memory:")
        self.addCleanup(self.connection.close)
        initialize(self.connection)
        self.connection.executemany(
            "INSERT INTO documents VALUES (?, ?, ?, ?, ?, ?)",
            [
                (7, "tenant", "owner", "Later", "Later body", None),
                (1, "tenant", "owner", "First", "First body", None),
                (2, "other tenant", "owner", "Private", "Private body", None),
                (3, "tenant", "other owner", "Private", "Private body", None),
                (4, "tenant", "owner", "Deleted", "Deleted body", "2026-01-01"),
                (5, "tenant", "owner", "Deleted", "Deleted body", ""),
                (6, "other tenant", "other owner", "Private", "Private body", None),
                (8, "tenant' OR 1=1 --", "O'Brien", "Quoted", "Quoted body", None),
            ],
        )

    def test_get_preserves_fields(self):
        self.assertEqual(
            get_document(self.connection, "tenant", "owner", 1),
            {"id": 1, "title": "First", "body": "First body"},
        )

    def test_unavailable_ids_all_return_none(self):
        for document_id in (2, 3, 4, 5, 6, 8, 99):
            with self.subTest(document_id=document_id):
                self.assertIsNone(
                    get_document(self.connection, "tenant", "owner", document_id)
                )

    def test_list_is_scoped_ordered_and_has_no_metadata(self):
        self.assertEqual(
            list_documents(self.connection, "tenant", "owner"),
            [
                {"id": 1, "title": "First", "body": "First body"},
                {"id": 7, "title": "Later", "body": "Later body"},
            ],
        )
        self.assertEqual(list_documents(self.connection, "missing", "owner"), [])
        self.assertEqual(list_documents(self.connection, "tenant", "missing"), [])

    def test_quoted_names_are_bound_literally(self):
        expected = {"id": 8, "title": "Quoted", "body": "Quoted body"}
        self.assertEqual(
            get_document(self.connection, "tenant' OR 1=1 --", "O'Brien", 8),
            expected,
        )
        self.assertEqual(
            list_documents(self.connection, "tenant' OR 1=1 --", "O'Brien"),
            [expected],
        )
        self.assertIsNone(
            get_document(self.connection, "tenant' OR 1=1 --", "O'Brien", 1)
        )
        self.assertEqual(
            list_documents(self.connection, "tenant", "owner' OR 1=1 --"), []
        )

    def test_document_id_is_bound(self):
        self.assertIsNone(
            get_document(self.connection, "tenant", "owner", "1 OR 1=1")
        )


if __name__ == "__main__":
    unittest.main()

